using Microsoft.AspNetCore.Mvc;
using Nafadh_Backend.DTOs;
using Nafadh_Backend.Enums;
using Nafadh_Backend.Services;

namespace Nafadh_Backend.Controllers
{
    // NEW: backs the Admin Communications hub (Company Conversations + Trainee
    // Complaints tabs), the Company portal's Contact page, and the Trainee
    // portal's upgraded Support page. See api-contract-shared-entities.md §1.
    [ApiController]
    [Route("api/[controller]")]
    public class ConversationController : ControllerBase
    {
        private readonly IConversationService _service;

        public ConversationController(IConversationService service)
        {
            _service = service;
        }

        // GET: api/Conversation?type=&participantUserId=&status=
        [HttpGet]
        public async Task<IActionResult> Get(
            [FromQuery] NFD_ConversationType? type,
            [FromQuery] int? participantUserId,
            [FromQuery] NFD_SupportTicketStatus? status)
        {
            var conversations = await _service.GetAsync(type, participantUserId, status);
            return Ok(conversations);
        }

        // GET: api/Conversation/{id}
        [HttpGet("{id}")]
        public async Task<IActionResult> GetById(int id)
        {
            var conversation = await _service.GetByIdAsync(id);
            if (conversation == null) return NotFound();
            return Ok(conversation);
        }

        // POST: api/Conversation
        [HttpPost]
        public async Task<IActionResult> Create([FromBody] CreateConversationDTO dto)
        {
            if (!ModelState.IsValid) return BadRequest(ModelState);

            var created = await _service.CreateAsync(dto);
            return CreatedAtAction(nameof(GetById), new { id = created.ConversationId }, created);
        }

        // POST: api/Conversation/{id}/messages
        [HttpPost("{id}/messages")]
        public async Task<IActionResult> AddMessage(int id, [FromBody] AddConversationMessageDTO dto)
        {
            if (!ModelState.IsValid) return BadRequest(ModelState);

            var message = await _service.AddMessageAsync(id, dto);
            return Ok(message);
        }

        // PUT: api/Conversation/{id}/status
        [HttpPut("{id}/status")]
        public async Task<IActionResult> UpdateStatus(int id, [FromBody] UpdateConversationStatusDTO dto)
        {
            await _service.UpdateStatusAsync(id, dto);
            return Ok(new { message = "Conversation status updated successfully." });
        }
    }
}
